@namespace sv_317310fc4d3c4b6090930374f948fd2f.Components.Pages.Apply

<nav class="step-indicator mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                 role="button"
                 @onclick="() => OnStepClick(step)"
                 style="cursor: @(isCompleted ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white" : "") @(isCompleted ? "bg-success text-white" : "") @(isFuture ? "bg-light text-muted border" : "")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : "") @(isCurrent ? "fw-bold" : "")">@StepNames[i]</small>
            </div>
        }
    </div>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; } = 1;
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

.step-indicator .step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
    font-weight: 600;
    transition: all 0.2s ease;
}

.step-indicator .step-item.dimmed {
    opacity: 0.5;
}

.step-indicator .step-item.completed:hover .step-circle {
    transform: scale(1.1);
}

@namespace sv_317310fc4d3c4b6090930374f948fd2f.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Company" @onchange="e => Update(company: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Title" @onchange="e => Update(title: e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd"))" disabled="@IsCurrent" @onchange="OnEndDateChanged" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="current-@Index" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                    <label class="form-check-label" for="current-@Index">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @onchange="e => Update(description: e.Value?.ToString())">@Description</textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(string? company = null, string? title = null,
        DateTime? startDate = null, DateTime? endDate = null,
        bool? isCurrent = null, string? description = null)
    {
        var data = new WorkEntryData(
            Index,
            company ?? Company,
            title ?? Title,
            startDate ?? StartDate,
            isCurrent ?? IsCurrent ? null : (endDate ?? EndDate),
            isCurrent ?? IsCurrent,
            description ?? Description);
        await OnChanged.InvokeAsync(data);
    }

    private Task OnStartDateChanged(ChangeEventArgs e) =>
        DateTime.TryParse(e.Value?.ToString(), out var d) ? Update(startDate: d) : Task.CompletedTask;

    private Task OnEndDateChanged(ChangeEventArgs e) =>
        DateTime.TryParse(e.Value?.ToString(), out var d) ? Update(endDate: d) : Task.CompletedTask;

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var current = (bool)(e.Value ?? false);
        return Update(isCurrent: current, endDate: current ? null : EndDate);
    }

    public record WorkEntryData(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@namespace sv_317310fc4d3c4b6090930374f948fd2f.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Name" @onchange="e => Update(name: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Relationship" @onchange="e => Update(relationship: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" value="@Email" @onchange="e => Update(email: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" value="@Phone" @onchange="e => Update(phone: e.Value?.ToString())" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var data = new ReferenceData(Index, name ?? Name, relationship ?? Relationship, email ?? Email, phone ?? Phone);
        await OnChanged.InvokeAsync(data);
    }

    public record ReferenceData(int Index, string Name, string Relationship, string Email, string Phone);
}

