        {
            IsValidating = true;
            StateHasChanged();
            try
            {
                var valid = await ValidateEmail(Email);
                if (!valid)
                {
                    emailInvalid = true;
                    ErrorMessage = "The email address is not valid.";
                    return;
                }
            }
            finally
            {
                IsValidating = false;
            }
        }

