               @onchange="e => { Email = e.Value?.ToString() ?? ""; emailInvalid = false; OnFieldChanged(); }" />
        @if (emailInvalid)
        {
            <div class="invalid-feedback">Please enter a valid email address.</div>
        }
    </div>
