@page "/apply"
@using sv_317310fc4d3c4b6090930374f948fd2f.Models
@namespace sv_317310fc4d3c4b6090930374f948fd2f.Components.Pages.Apply

@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="() => GoToStep(4)"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="isSubmitting"
                        Submitted="submitted"
                        ApplicationId="applicationId"
                        ErrorMessage="@submitError" />
            break;
    }
</div>

@code {
    private int currentStep = 1;

    // Step 1
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4
    private string coverLetter = "";

    // Submission
    private bool isSubmitting;
    private bool submitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5)
            currentStep = step;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        fullName = result.FullName;
        email = result.Email;
        phone = result.Phone;
        address = result.Address;
        currentStep = 2;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 4;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var app = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(app);
            submitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

